return "    #获取聊天数据\n    get_chat_data 29000 {\n        response {\n            roomid 0 : integer #分配的房间id\n            private_new 1 : boolean #是否有私聊消息\n        }\n    }\n    .chat_message {\n        id 0 : integer #消息序列\n        channel 1 : integer #聊天频道\n        roomid 2 : integer #房间id\n        playerid 3 : integer #消息发送者id\n        head_sculpture 4 : integer #头像\n        name 5 : string # 昵称\n        message 6 : string #聊天内容\n        time 7 : integer #消息发送时间\n    }\n\n    #发送聊天消息\n    send_chat_message 29001 {\n        request {\n            channel 0 : integer  # 1 私聊 2 城市频道 3 世界频道 4 系统通知  5 工会\n            playerid 1 : integer # 私聊用户id\n            message 2 : string # 聊天内容\n        }\n        response {\n            result 0 : integer # 1 成功 2 只能发私信给好友 3 未知频道 4 被禁言 5 消息非法\n        }\n    }\n\n    #拉取聊天消息\n    fetch_chat_message 29002 {\n        request {\n            channel 0 : integer # 1 私聊 2 城市频道 3 世界频道 4 系统通知  5 工会\n        }\n        response {\n            result 0 : integer # 1 成功 2 失败\n            list 1 : *chat_message\n            finish 2 : boolean #列表拉取完成\n        }\n    }\n\n    #切换聊天房间\n    change_chat_room 29003 {\n        request {\n            roomid 0 : integer\n        }\n        response {\n            result 0 : integer # 1 成功 2 失败\n            roomid 1 : integer # 新房间id 可能没有变化\n            list 2 : *chat_message #该房间的最近50条聊天记录  如果房间实际变化才会有该字段\n        }\n    }\n\n"
